import java.util.*;

public class Main {
    boolean isValid(String s) {
        while (s.contains("()") || s.contains("[]") || s.contains("{}")) {          // repeatedly erase any innermost matched pair
            s = s.replace("()", "").replace("[]", "").replace("{}", "");
        }
        return s.isEmpty();                                                            // valid only if EVERYTHING cancels out completely
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.isValid("()[]{}"));
        System.out.println(solution.isValid("([)]"));
    }
}

