bool isValid(string s) {
    size_t pos;
    while ((pos = s.find("()")) != string::npos ||                                  // repeatedly erase any innermost matched pair
           (pos = s.find("[]")) != string::npos ||
           (pos = s.find("{}")) != string::npos) {
        s.erase(pos, 2);
    }
    return s.empty();                                                                  // valid only if EVERYTHING cancels out completely
}

int main() {
    cout << boolalpha << isValid("()[]{}") << endl;
    cout << boolalpha << isValid("([)]") << endl;
    return 0;
}

