import java.util.*;

public class Main {
    boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{');           // maps each closing bracket to its expected opening match
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);                                                                // push every opening bracket
            } else {
                if (stack.isEmpty() || stack.pop() != pairs.get(c)) return false;                 // a closing bracket must match the MOST RECENT unmatched opening one
            }
        }
        return stack.isEmpty();                                                                // valid only if every opening bracket found its match
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.isValid("()[]{}"));
        System.out.println(solution.isValid("([)]"));
    }
}

