#include <bits/stdc++.h>
using namespace std;

bool isValid(string s) {
    stack<char> st;
    unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};              // maps each closing bracket to its expected opening match
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);                                                                       // push every opening bracket
        } else {
            if (st.empty() || st.top() != pairs[c]) return false;                                // a closing bracket must match the MOST RECENT unmatched opening one
            st.pop();
        }
    }
    return st.empty();                                                                       // valid only if every opening bracket found its match
}

int main() {
    cout << boolalpha << isValid("()[]{}") << endl;
    cout << boolalpha << isValid("([)]") << endl;
    return 0;
